def canPartition(nums, target):
    n = len(nums)
    total_masks = 1 << n

    for mask in range(1, total_masks - 1):
        prod1 = 1
        valid1 = True
        for i in range(n):
            if (mask >> i) & 1:
                prod1 *= nums[i]
                if prod1 > target:
                    valid1 = False
                    break
        if not valid1 or prod1 != target:
            continue

        # Build the complement subset
        prod2 = 1
        valid2 = True
        for i in range(n):
            if not (mask >> i) & 1:
                prod2 *= nums[i]
                if prod2 > target:
                    valid2 = False
                    break
        if valid2 and prod2 == target:
            return True

    return False
